protected void postCreateRebatePostingAccount(
    TAMRebatePostingAccount _rebatePostingAccount,
    TAMRebateDeal _rebateDeal,
    TAMRebatePostingId _postingId,
    TAMRebateTransactionType _rebateTransactionType)
{
    next postCreateRebatePostingAccount(_rebatePostingAccount, _rebateDeal, _postingId, _rebateTransactionType);

    if (!FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        return;
    }

    if (_rebateDeal.Recipient && 
        _rebateTransactionType == TAMRebateTransactionType::Rebate &&
        TAMRebatePosting::find(_postingId, _rebateDeal.ModuleInventCustVend).RebatePostingType == TAMRebatePostingAccountType::CustVend
       )
    {
        _rebatePostingAccount.Recipient = _rebateDeal.Recipient;
    }
}
